SELECT CASE WHEN budget >= 3371000 THEN 'high' WHEN budget >= 1066000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, ROUND(AVG(budget), 2) AS avg_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT(DISTINCT budget) AS unique_locations FROM departments GROUP BY CASE WHEN budget >= 3371000 THEN 'high' WHEN budget >= 1066000 THEN 'mid' ELSE 'low' END, location HAVING ROUND(AVG(budget), 2) >= 74
